command:
$ErrorActionPreference = "Stop"
Write-Host "===== BOOKMARK PRE-MAIN VALIDATION ====="
git fetch origin main work/bookmarks-winui --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "git fetch failed" }
$status = @(git status --short)
Write-Host "LOCAL_BRANCH=$(git branch --show-current)"
Write-Host "LOCAL_HEAD=$(git rev-parse HEAD)"
Write-Host "ORIGIN_MAIN=$(git rev-parse origin/main)"
if ($status.Count -ne 0) {
  $status | ForEach-Object { Write-Host $_ }
  throw "persistent checkout has unexpected local changes"
}
if ((git branch --show-current) -ne "main") {
  git checkout main
  if ($LASTEXITCODE -ne 0) { throw "cannot checkout main" }
}
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "cannot fast-forward local main" }
if ((git rev-parse HEAD).Trim() -ne "5228cbbfc24f56d61a84975545f1d8572e7deece") {
  throw "main moved after request snapshot"
}

Write-Host "BUILD_CURRENT_MAIN_FOR_BEFORE"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "current main Release build failed" }

$capture = @'
from pathlib import Path
import ctypes as c
import os, shutil, subprocess, time
from ctypes import wintypes as W
from pywinauto import Desktop
from PIL import ImageGrab

ROOT=Path.cwd()
EXE=ROOT/"out"/"winui"/"Release"/"flyExplorer.exe"
owned=ROOT/"logs"/"bookmark-visual-owned"
if owned.exists(): shutil.rmtree(owned,ignore_errors=True)
source=owned/"북마크원본"
appdata=owned/"appdata"; localdata=owned/"localdata"; temp=owned/"tmp"
for p in (source,appdata,localdata,temp): p.mkdir(parents=True,exist_ok=True)
(source/"owned.txt").write_text("bookmark visual owned",encoding="utf-8")
profile=localdata/"flyExplorer";profile.mkdir()
(profile/"ui-preferences-v1.txt").write_bytes(
 b"schema=2\r\nlanguage=ko-KR\r\ntheme=dark\r\nview=details\r\n")
mode=os.environ.get("BOOKMARK_VISUAL_MODE","before")
if mode=="after":
 (profile/"bookmarks-v1.txt").write_text(
  "schema=1\r\n자주 쓰는 폴더\t"+str(source)+"\r\n",encoding="utf-8",newline="")
env={**os.environ,"APPDATA":str(appdata),"LOCALAPPDATA":str(localdata),
     "TEMP":str(temp),"TMP":str(temp)}
p=subprocess.Popen([str(EXE),str(source)],cwd=EXE.parent,env=env,
 stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
u=c.windll.user32
CALL=c.WINFUNCTYPE(W.BOOL,W.HWND,W.LPARAM)
u.EnumWindows.argtypes=[CALL,W.LPARAM]
u.GetWindowThreadProcessId.argtypes=[W.HWND,c.POINTER(W.DWORD)]
u.PostMessageW.argtypes=[W.HWND,W.UINT,W.WPARAM,W.LPARAM]
u.SetWindowPos.argtypes=[W.HWND,W.HWND,c.c_int,c.c_int,c.c_int,c.c_int,W.UINT]
def wins():
 out=[]
 @CALL
 def cb(h,_):
  pid=W.DWORD();u.GetWindowThreadProcessId(h,c.byref(pid))
  if pid.value==p.pid and u.IsWindowVisible(h):out.append(int(h))
  return 1
 u.EnumWindows(cb,0);return out
limit=time.monotonic()+18
while time.monotonic()<limit and not wins() and p.poll() is None:time.sleep(.15)
assert p.poll() is None and wins(),"visual fixture window missing"
hwnd=wins()[0];u.SetWindowPos(hwnd,0,120,70,972,720,0x0040)
win=Desktop(backend="uia").window(handle=hwnd)
address=win.child_window(auto_id="AddressBox")
limit=time.monotonic()+18
while time.monotonic()<limit:
 try:
  if str(source).lower() in address.get_value().lower():break
 except Exception:pass
 time.sleep(.15)
else:raise AssertionError("visual fixture navigation did not settle")
time.sleep(.45)
r=win.rectangle()
target=ROOT/"logs"/f"bookmark-visual-{mode}.png"
ImageGrab.grab(bbox=(r.left,r.top,r.right,r.bottom),
 include_layered_windows=True).save(target)
u.PostMessageW(hwnd,0x0010,0,0);p.wait(timeout=12)
assert p.returncode==0,p.returncode
print("BOOKMARK_VISUAL_CAPTURE",mode,target,"EXIT",p.returncode,flush=True)
shutil.rmtree(owned,ignore_errors=True)
'@
Set-Content -LiteralPath "logs\capture-bookmark-visual.py" -Value $capture -Encoding utf8
$env:BOOKMARK_VISUAL_MODE = "before"
python -X utf8 logs\capture-bookmark-visual.py
if ($LASTEXITCODE -ne 0) { throw "before capture failed" }

if (git show-ref --verify --quiet refs/heads/work/bookmarks-winui) {
  git checkout work/bookmarks-winui
  if ($LASTEXITCODE -ne 0) { throw "cannot checkout local bookmark branch" }
  git merge --ff-only origin/work/bookmarks-winui
  if ($LASTEXITCODE -ne 0) { throw "cannot fast-forward bookmark branch" }
} else {
  git checkout -b work/bookmarks-winui --track origin/work/bookmarks-winui
  if ($LASTEXITCODE -ne 0) { throw "cannot create local bookmark branch" }
}
Write-Host "BOOKMARK_BRANCH_HEAD=$(git rev-parse HEAD)"
Write-Host "SOURCE_CONTRACTS"
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
Write-Host "NATIVE_RELEASE"
cmd /c tests\winui\m20\build.cmd Release
if ($LASTEXITCODE -ne 0) { throw "M20 Release build failed" }
cmd /c "set FLY_M20_CONFIG=Release&& python -X utf8 tests\winui\m20\test_native.py"
if ($LASTEXITCODE -ne 0) { throw "M20 Release native test failed" }
Write-Host "BUILD_CHANGED_RELEASE"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "changed Release build failed" }
Write-Host "OWNED_GUI_RELEASE"
python -X utf8 tools\winui\run_checks.py gui --configuration Release
if ($LASTEXITCODE -ne 0) { throw "owned Release GUI failed" }
$env:BOOKMARK_VISUAL_MODE = "after"
python -X utf8 logs\capture-bookmark-visual.py
if ($LASTEXITCODE -ne 0) { throw "after capture failed" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }
Write-Host "FINAL_STATUS"
git status --short
Write-Host "BOOKMARK_PREMAIN_VALIDATION_PASS"
